import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div
      data-slot="component-preview"
      className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-6 p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
    >
      {children}
    </div>
  );
}

import * as React from "react";

import { ScrollArea } from "@/registry/erbium/ui/scroll-area";
import { Separator } from "@/registry/erbium/ui/separator";

const tags = Array.from({ length: 50 }).map((_, i, a) => `v1.2.0-beta.${a.length - i}`);

export default function ScrollAreaDemo() {
  return (
    <ScrollArea className="h-72 w-48 rounded-xl border surface-panel">
      <div className="p-4">
        <h4 className="mb-4 text-sm leading-none font-medium">Tags</h4>
        {tags.map((tag) => (
          <React.Fragment key={tag}>
            <div className="text-sm">{tag}</div>
            <Separator className="my-2" />
          </React.Fragment>
        ))}
      </div>
    </ScrollArea>
  );
}

import { ScrollArea } from "@/registry/erbium/ui/scroll-area";

export interface Artwork {
  artist: string;
  art: string;
}

export const works: Artwork[] = [
  {
    artist: "Ornella Binni",
    art: "https://images.unsplash.com/photo-1465869185982-5a1a7522cbcb?auto=format&fit=crop&w=300&q=80",
  },
  {
    artist: "Tom Byrom",
    art: "https://images.unsplash.com/photo-1548516173-3cabfa4607e9?auto=format&fit=crop&w=300&q=80",
  },
  {
    artist: "Vladimir Malyavko",
    art: "https://images.unsplash.com/photo-1494337480532-3725c85fd2ab?auto=format&fit=crop&w=300&q=80",
  },
];

export function ScrollAreaHorizontalDemo() {
  return (
    <ScrollArea
      fade="horizontal"
      orientation="horizontal"
      className="w-96 rounded-xl border surface-panel whitespace-nowrap"
    >
      <div className="flex w-max space-x-4 p-4">
        {works.map((artwork) => (
          <figure key={artwork.artist} className="shrink-0">
            <div className="overflow-hidden rounded-md">
              <img
                src={artwork.art}
                alt={`Photo by ${artwork.artist}`}
                className="aspect-[3/4] h-fit w-fit object-cover"
                width={300}
                height={400}
              />
            </div>
            <figcaption className="pt-2 text-xs text-muted-foreground">
              Photo by <span className="font-semibold text-foreground">{artwork.artist}</span>
            </figcaption>
          </figure>
        ))}
      </div>
    </ScrollArea>
  );
}

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { ScrollArea } from "@/registry/erbium/ui/scroll-area";

import PlaygroundExample from "./variants/playground";

const PlaygroundSource = "import { ScrollArea } from \"@/registry/erbium/ui/scroll-area\";\nimport type * as React from \"react\";\n\nconst Example = (args: React.ComponentProps<typeof ScrollArea>) => (\n  <ScrollArea {...args} className=\"h-40 w-72 rounded-xl border surface-panel\">\n    <div className=\"space-y-2 p-4\">\n      {Array.from({ length: 12 }, (_, index) => (\n        <p key={index}>Scrollable row {index + 1}</p>\n      ))}\n    </div>\n  </ScrollArea>\n);\n\nexport default Example;\n";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from \"../examples/scroll-area-demo\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <Demo />\n  </div>\n);\n\nexport default Example;\n";

import HorizontalExample from "./variants/horizontal";

const HorizontalSource = "import { ScrollAreaHorizontalDemo } from \"../examples/scroll-area-horizontal-demo\";\n\nconst Example = () => <ScrollAreaHorizontalDemo />;\n\nexport default Example;\n";

const meta = {
  component: ScrollArea,
  tags: ["autodocs"],
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: "## Usage\n\nPreserve native scrolling while applying custom styling across browsers.\n\n**Import:** `@/registry/erbium/ui/scroll-area`\n\n## Usage\n\n```tsx\nimport { ScrollArea, ScrollBar } from \"@/registry/erbium/ui/scroll-area\";\n```\n\n```tsx\n<ScrollArea className=\"h-[200px] w-[350px] rounded-xl border surface-panel p-4\">\n  Your scrollable content here.\n</ScrollArea>\n```\n\n## Composition\n\nUse the following composition to build a `ScrollArea`:\n\n```text\nScrollArea\n└── ScrollBar\n```\n\n## Base UI documentation\n\nExplore the underlying primitives and their API reference.\n\n- [Scroll Area](https://base-ui.com/react/components/scroll-area)",
      },
    },
  },
} satisfies Meta<typeof ScrollArea>;

export default { ...meta, title: "Layout & containers/Scroll Area",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<typeof ScrollArea> = {
  args: { fade: "vertical", scrollbar: "thin", scrollbarVisibility: "always" },
  argTypes: {
    fade: { control: "select", options: ["vertical", "horizontal", false] },
    scrollbar: { control: "select", options: ["thin", "default", "none"] },
    scrollbarVisibility: { control: "select", options: ["always", "hover", "scroll"] },
  },
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

export const Horizontal: Story = {
  parameters: {
    docs: {
      description: { story: "Set `orientation=\"horizontal\"` (or `\"both\"`) for a horizontal scrollbar, and `fade=\"horizontal\"` to fade the start and end edges." },
      source: { code: HorizontalSource },
    },
  },
  render: HorizontalExample,
};

import { ScrollAreaHorizontalDemo } from "../examples/scroll-area-horizontal-demo";

const Example = () => <ScrollAreaHorizontalDemo />;

export default Example;

import Demo from "../examples/scroll-area-demo";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <Demo />
  </div>
);

export default Example;

